local _, T = ...
T:RegisterPage("convenience", {key = "market", label = "Gear Report", order = 4.1, build = function(p)
    local cfg = function() return T.db.market end
    p:Section("Gear Report", "Help improve Gear Advisor by sending the author a short report from your character: your class and level, your talent points and tree, and the stat names on your gear. A notice explains what the report holds. If you continue, Tempus sends it in the background, as a few whispers to the character for your faction as soon as that character is online. It checks every 30 minutes while you are logged in.")
    p:Add(T.UI.W.Button("Share my gear data", function() T:StartGearReport() end, "Shows what the report contains. If you continue, it is sent in the background, as whispers, once the receiving character is online.", 200))
    p:Section("Auction values", "Shows the lowest buyout from Tempus's own auction house scan on item tooltips, including stack estimates in Tempus bags. Prices are shared by all your characters on the realm. Listing prices are estimates, not completed sales.")
    p:Check(cfg, "tooltips", "Show auction estimates on item tooltips")
    p:Slider(cfg, "staleDays", "Mark prices stale after", 1, 14, 1, function(v) return v .. " days" end)
    p:Section("Scanning", "Open the auction house and click Tempus scan in the top-left corner of its window, or the button below. A scan reads every listing in one request and keeps the lowest buyout per item. The game allows one full scan about every 15 minutes.")
    p:Check(cfg, "autoScan", "Scan automatically when I open the auction house")
    p:Add(T.UI.W.Button("Scan auction house", function() T.Market:StartScan() end, "Reads the whole auction house once. Does not buy, sell or post anything.", 200))
    p:Section("Gear Advisor", "The Gear Advisor button in the top-left corner of the auction house window, or /tempus gear from anywhere, lists the best gear deals from your last scan: items above what you wear in that slot, that you can equip, ranked by how much your stats improve for the price, so a nearly free +1 does not top the list and gear with the wrong stats for your class is left out.")
    p:Add(T.UI.W.Button("Open Gear Advisor", function() T.Market:ToggleUpgrades() end, "Opens the list from your last scan. It works anywhere; you do not need the auction house open. Drag it to move it. Also /tempus gear.", 200))
    p:Dropdown(cfg, "upgradeSort", "Rank upgrades by", { { "VALUE", "Best value (stats for the price)" }, { "BIGGEST", "Biggest upgrade" }, { "GAIN", "Most item levels" }, { "CHEAPEST", "Cheapest first" }, { "NAME", "Name" }, { "LEGACY", "Item levels per gold (old method, no stat check)" } })
    local _, class = UnitClass("player")
    local roles = T.GearAdvisor and T.GearAdvisor.Scoring and T.GearAdvisor.Scoring.RoleList(class)
    if roles then
        p:Dropdown(cfg, "gearRole", "Score gear as", roles, "Which build to judge gear for. For a Druid, Automatic follows your shapeshift form (Cat Form scores as Cat) and remembers the last one; for other classes it is a guess, so pick yours. The weights are community estimates from GearQuest Forever, shown as estimates.")
    end
    p:Slider(cfg, "planGold", "Budget plan gold (0 = all I carry)", 0, 5000, 10, function(v) return v == 0 and "All my gold" or (v .. "g") end, "How much gold the budget plan may spend.")
    p:Add(T.UI.W.Button("Show budget plan", function() T.Market:PrintPlan() end, "Prints the best set of gear to buy for that gold, from your last scan, in chat. Nothing is bought. Also /tempus gearplan 50.", 200))
    p:Slider(cfg, "upgradeMinGain", "Minimum item level gain", 1, 30, 1, function(v) return "+" .. v end)
    p:Slider(cfg, "upgradeMaxGold", "Maximum price (gold, 0 = no limit)", 0, 1000, 5, function(v) return v == 0 and "No limit" or (v .. "g") end, "Hides upgrades that cost more than this per item. You can also type a price in the Gear Advisor window.")
    p:Check(cfg, "upgradeAffordable", "Only show gear I can afford")
    p:Check(cfg, "upgradeUseAHFilters", "Use the auction house filters", "The list follows the rarity and level range set in the auction house search filter, once you have opened the auction house this session.")
    p:Paragraph("Items with no scan data show 'No scanned price'; older prices are marked stale. Re-hover an item after a scan to see its updated estimate.")
end})
